import{_ as a,o as s,c as i,aF as t}from"./chunks/framework.CNkxH4QO.js";const k=JSON.parse('{"title":"krawler-atlas","description":"A Krawler based job to download geographical boundary data (Admin Express, OSM, BDPR).","frontmatter":{"title":"krawler-atlas","description":"A Krawler based job to download geographical boundary data (Admin Express, OSM, BDPR)."},"headers":[],"relativePath":"packages/krawler-atlas/index.md","filePath":"packages/krawler-atlas/index.md"}'),n={name:"packages/krawler-atlas/index.md"};function l(r,e,o,p,h,d){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="krawler-atlas" tabindex="-1">krawler-atlas <a class="header-anchor" href="#krawler-atlas" aria-label="Permalink to &quot;krawler-atlas&quot;">​</a></h1><p><em>A Krawler based job to download geographical boundary data (Admin Express, OSM, BDPR).</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><a href="https://kalisio.github.io/krawler/" target="_blank" rel="noreferrer">Krawler</a> based jobs to scrape various data related to administrative entities.</p><h2 id="osm-boundaries" tabindex="-1">OSM boundaries <a class="header-anchor" href="#osm-boundaries" aria-label="Permalink to &quot;OSM boundaries&quot;">​</a></h2><p>This job relies on:</p><ul><li><a href="https://osmcode.org/osmium-tool" target="_blank" rel="noreferrer">osmium</a> to extract administrative boundaries at different level from OSM pbf files,</li><li><a href="https://gdal.org/programs/ogr2ogr.html" target="_blank" rel="noreferrer">ogr2ogr</a> to generate sequential GeoJson files to handle large datasets,</li><li><a href="https://github.com/mbloch/mapshaper" target="_blank" rel="noreferrer">mapshaper</a> to simplify complex geometries,</li><li><a href="https://github.com/felt/tippecanoe" target="_blank" rel="noreferrer">tippecanoe</a> to generate MBTiles,</li><li><a href="https://turfjs.org/" target="_blank" rel="noreferrer">turfjs</a> to compute the position of toponyms.</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>osmium, ogr, mapshaper and tippecanoe command-line tools must be installed on your system.</p></div><p>To setup the regions to process, you must export the environment variables <code>REGIONS</code> with the <a href="https://download.geofabrik.de/" target="_blank" rel="noreferrer">GeoFabrik</a> regions. For instance:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> REGIONS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;europe/france;europe/albania&quot;</span></span></code></pre></div><p>If you&#39;d like to simplify geometries you can setup the simplification tolerance and algorithm:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SIMPLIFICATION_TOLERANCE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # defaults to 128</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SIMPLIFICATION_ALGORITHM</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">visvalingam </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># defaults to &#39;db&#39;</span></span></code></pre></div><blockquote><p>Note</p><p>The given simplification tolerance will be scaled according to administrative level using this formula: <code>tolerance at level N = tolerance / 2^(N-2)</code></p></blockquote><p>If you only need some languages for i18n properties (<code>name</code>, <code>alt_name</code> and <code>official_name</code>) in database you can select the target languages like this:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LANGUAGES</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;en;fr&quot;</span></span></code></pre></div><p>For testing purpose you can also limit the processed administrative levels using the <code>MIN_LEVEL/MAX_LEVEL</code> environment variables.</p><h3 id="planet-generation" tabindex="-1">Planet generation <a class="header-anchor" href="#planet-generation" aria-label="Permalink to &quot;Planet generation&quot;">​</a></h3><p>To generate the whole planet use continent extracts like this first to launch the <code>osm-boundaries</code> job from level 3 to 8:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> REGIONS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;africa;asia;australia-oceania;central-america;europe;north-america;south-america&quot;</span></span></code></pre></div><p>As large files are generated for e.g. Europe you might have to increase the default NodeJS memory limit:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> NODE_OPTIONS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--max-old-space-size</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8192</span></span></code></pre></div><p>Then, launch the <code>osm-planet-boundaries</code> job for level 2, which uses a planet extract, and planet MBTiles generation. Indeed, country-level (i.e. administrative level 2) requires a whole planet file to avoid missing relation between continental and islands areas.</p><p>Last but not least, launch the <code>generate-osm-boundaries-mbtiles.sh</code> script to generate a MBTiles file from GeoJson files produced by the job or <code>generate-osm-boundaries-gpkg.sh</code> script to generate a GPKG file.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>GPKG generation requires the <code>ogrmerge</code> tool to be installed, if you are using an unstable debian version you can do this, which is not <a href="https://wiki.debian.org/DontBreakDebian#Don.27t_make_a_FrankenDebian" target="_blank" rel="noreferrer">recommanded</a> for a stable version:</p></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nano</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/apt/sources.list</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Edit file and add this line</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">deb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://deb.debian.org/debian/</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unstable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contrib</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> non-free</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Then install GDAL dev version to get ogrmerge</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libgdal-dev</span></span></code></pre></div><p>To avoid generating data multiple times you can easily dump/restore it from/to MongoDB databases:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mongodump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host=localhost</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port=27017</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --username=user</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --password=password</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --db=atlas</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --collection=osm-boundaries</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --gzip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dump</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mongorestore</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --db=atlas</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --gzip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host=mongodb.example.net</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port=27018</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --username=user</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --password=password</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --collection=osm-boundaries</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dump/atlas/osm-boundaries.bson.gz</span></span></code></pre></div><p>If you dump the collection first recreate required indices to speed-up data access with the Mongo shell like:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>db[&#39;admin-express&#39;].createIndexes([{ geometry: &#39;2dsphere&#39; }, { &#39;properties.layer&#39;: 1 }, { geometry: &#39;2dsphere&#39;, &#39;properties.layer&#39;: 1 }])</span></span>
<span class="line"><span>db[&#39;osm-boundaries&#39;].createIndexes([{ geometry: &#39;2dsphere&#39; }, { &#39;properties.admin_level&#39;: 1 }, { geometry: &#39;2dsphere&#39;, &#39;properties.admin_level&#39;: 1 }])</span></span></code></pre></div><h2 id="admin-express" tabindex="-1">Admin-Express <a class="header-anchor" href="#admin-express" aria-label="Permalink to &quot;Admin-Express&quot;">​</a></h2><p>This job relies on archive shape files from IGN and the <a href="https://github.com/mbloch/mapshaper" target="_blank" rel="noreferrer">mapshaper</a> and <a href="https://www.7-zip.org/download.html" target="_blank" rel="noreferrer">7z</a> tools.</p><p><a href="https://geoservices.ign.fr/documentation/diffusion/telechargement-donnees-libres.html#admin-express" target="_blank" rel="noreferrer">https://geoservices.ign.fr/documentation/diffusion/telechargement-donnees-libres.html#admin-express</a></p><h3 id="with-french-polynesia" tabindex="-1">with French Polynesia <a class="header-anchor" href="#with-french-polynesia" aria-label="Permalink to &quot;with French Polynesia&quot;">​</a></h3><p>The job has been updated to include French Polynesia data in the admin-express dataset.</p><p>The script requires the following tools:</p><ul><li><code>mapshaper</code> (can be installed with <code>npm install -g mapshaper</code>)</li><li><code>wget</code>, <code>7z</code>, <code>tippecanoe</code> and <code>tile-join</code>. All of those can probably be found as packages in your favorite distribution (<code>apt install 7z wget tippecanoe</code>).</li></ul><p>French Polynesia data is fetched from <a href="https://www.data.gouv.fr/fr/datasets/limites-geographiques-administratives/" target="_blank" rel="noreferrer">here</a> and <a href="https://www.tefenua.data.gov.pf/maps/6e392df616c949309eda19656450562a/about" target="_blank" rel="noreferrer">here</a> for the INSEE codes.</p><p>The script reprojects and patches the French Polynesia data to match the Admin Express schema, adding properties like <code>INSEE_COM</code>, <code>INSEE_DEP</code>, <code>NOM</code>, <code>NOM_M</code> and <code>POPULATION</code> to it. It then merges with the Admin Express dataset to build the final mbtiles.</p><h2 id="bdpr" tabindex="-1">BDPR <a class="header-anchor" href="#bdpr" aria-label="Permalink to &quot;BDPR&quot;">​</a></h2><p>This job relies on archive shape files from IGN and the <a href="https://github.com/mbloch/mapshaper" target="_blank" rel="noreferrer">mapshaper</a> and <a href="https://www.7-zip.org/download.html" target="_blank" rel="noreferrer">7z</a> tools.</p><p><a href="https://geoservices.ign.fr/documentation/diffusion/telechargement-donnees-libres.html#bdpr" target="_blank" rel="noreferrer">https://geoservices.ign.fr/documentation/diffusion/telechargement-donnees-libres.html#bdpr</a></p><h2 id="bdtopage" tabindex="-1">BDTOPAGE <a class="header-anchor" href="#bdtopage" aria-label="Permalink to &quot;BDTOPAGE&quot;">​</a></h2><p>This job relies on:</p><ul><li><a href="https://www.7-zip.org/download.html" target="_blank" rel="noreferrer">7z</a> to extract archive shape files from eaufrance</li><li><a href="https://github.com/mbloch/mapshaper" target="_blank" rel="noreferrer">mapshaper</a> to convert shape files to GeoJson</li><li><a href="https://github.com/felt/tippecanoe" target="_blank" rel="noreferrer">tippecanoe</a> to generate MBTiles (optional)</li></ul><p>BDTOPAGE contains hydrographic data for the french territory and includes the following layers:</p><ul><li>Watercourses</li><li>Water bodies</li><li>Elementary surfaces</li><li>Hydrographic sections</li><li>Hydrographic nodes</li><li>Land-sea boundaries</li><li>Hydrographic basins (medium scale)</li><li>Topographic watershed (medium scale)</li></ul><p>To select specific layers to process you can setup the <code>TOPAGE_LAYERS</code> environment variable with a comma-separated list of <code>&lt;layer_name&gt;=&lt;output_name&gt;</code> entries like this:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TOPAGE_LAYERS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;BassinHydrographique_FXX=hydrographic-basins,BassinVersantTopographique_FXX=topographic-watersheds&quot;</span></span></code></pre></div><p>bash script to generate mbtiles from bdtopage data:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./generate-bdtopage-mbtiles.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">output_di</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">geojson_fil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">layer_name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">optional</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Two directories will be created:</p><ul><li><code>bdtopage-output/geojson/</code> containing one geojson file per layer</li><li><code>bdtopage-output/mbtiles/</code> containing one mbtiles file per layer</li><li><code>bdtopage-output/shapefiles/</code> containing the original shapefiles unzipped</li><li><code>bdtopage-workdir/</code> temporary working directory</li></ul><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><p>We personally use <a href="https://kalisio.github.io/kargo/" target="_blank" rel="noreferrer">Kargo</a> to deploy the service.</p>`,54)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
